/**
 * Regenerates the thin route handlers that serve each sitemap file.
 *
 * All sitemap *logic* lives in src/lib/sitemap.ts and is entirely
 * locale-driven; these files exist only because Next.js resolves routes from
 * the filesystem and does not support a dynamic segment inside a path
 * segment (`sitemap-[group].xml` is not a route). Each generated file is
 * five lines and holds no logic.
 *
 * Publishing a locale is therefore: flip `published` in the locale config,
 * add its route manifest and content, then run this script.
 *
 *   node scripts/i18n/gen-sitemap-routes.mjs
 */
import { readFileSync, writeFileSync, mkdirSync, readdirSync, rmSync } from "node:fs";

const groups = ["tools", "hubs", "guides", "comparisons", "pages"];

// Parse the locale config rather than importing it: this is a plain Node
// script and the config is TypeScript.
const localesSrc = readFileSync("src/lib/i18n/locales.ts", "utf8");
const blocks = [...localesSrc.matchAll(/code:\s*"([^"]+)",\s*prefix:\s*"([^"]*)"[\s\S]*?published:\s*(true|false),/g)];
const published = blocks
  .map(([, code, prefix, pub]) => ({ code, prefix, published: pub === "true" }))
  .filter((l) => l.published);

if (published.length === 0) throw new Error("No published locales parsed");

const DEFAULT_LOCALE = "en";
const wanted = new Map();
for (const locale of published) {
  for (const group of groups) {
    const name = locale.code === DEFAULT_LOCALE ? group : `${group}-${locale.prefix}`;
    wanted.set(`sitemap-${name}.xml`, { group, locale: locale.code });
  }
}

for (const [dir, { group, locale }] of wanted) {
  mkdirSync(`src/app/${dir}`, { recursive: true });
  writeFileSync(
    `src/app/${dir}/route.ts`,
    `import { urlsetXml, XML_HEADERS } from "@/lib/sitemap";

// GENERATED by scripts/i18n/gen-sitemap-routes.mjs — do not edit by hand.
export const dynamic = "force-static";

export function GET() {
  return new Response(urlsetXml("${group}", "${locale}"), { headers: XML_HEADERS });
}
`,
  );
}

// Remove handlers for locales that are no longer published, so an
// unpublished locale cannot keep serving a live sitemap.
for (const entry of readdirSync("src/app", { withFileTypes: true })) {
  if (!entry.isDirectory()) continue;
  if (!/^sitemap-.*\.xml$/.test(entry.name)) continue;
  if (!wanted.has(entry.name)) {
    rmSync(`src/app/${entry.name}`, { recursive: true, force: true });
    console.log(`Removed stale ${entry.name}`);
  }
}

console.log(`Wrote ${wanted.size} sitemap route handlers.`);
